/// <reference types="vite/client" />

// Déclare les modules pour les types d'images courants
declare module '*.png' {
    const value: any;
    export default value;
  }
  
  declare module '*.svg' {
    const value: any;
    export default value;
  }
  
  declare module '*.jpeg' {
    const value: any;
    export default value;
  }
  
  declare module '*.jpg' {
    const value: any;
    export default value;
  }
  
  declare module '*.webp' {
    const value: any;
    export default value;
  }